class OutfitAdvisor:
    def recommend(self, profile: WeatherProfile):
        score = profile.temp - (profile.wind * 0.1)
        if profile.is_precip:
            score -= 3
        if profile.condition == "hail":
            score -= 6
        if profile.temp < 0:
            return ["parka", "boots", "gloves"]
