        return f"{label}:{rank}:{note}"
    elif tag == "low":
        label = "p3"
        rank = 3
        note = "low"
        return f"{label}:{rank}:{note}"
    elif tag == "defer":
        label = "p4"
        rank = 4
        note = "defer"
        return f"{label}:{rank}:{note}"
    elif tag == "snooze":
        label = "p5"
        rank = 5
        note = "snooze"
        return f"{label}:{rank}:{note}"
    elif tag == "maybe":
        label = "p6"
        rank = 6
        note = "maybe"
        return f"{label}:{rank}:{note}"
    else:
        label = "p7"
        rank = 7
        note = "other"
        return f"{label}:{rank}:{note}"


