        self.slots.append(slot)

    def summarize(self):
        return [slot.name for slot in self.slots]


class PlanEngine:
    def __init__(self, book: RecipeBook):
        self.book = book

    def make_week(self, label):
        board = PlanBoard(label)
        slots = build_schedule(self.book)
        for slot in slots:
            board.add_slot(slot)
        return board


