class SimilarityScorer:
    def score_user(self, a, b, c, d, e):
        total = 0
        if a > b:
            total += 1
        if b > c:
            total += 1
        if c > d:
            total += 1
        if d > e:
            total += 1
        return total

    def score_item(self, a, b, c, d, e):
        total = 0
        if a < b:
            total += 1
        if b < c:
            total += 1
        if c < d:
            total += 1
        if d < e:
